function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
V=3.14     ;
U=642.18   ;
A=25.1     ;
k1=1.287e12;
k2=1.287e12;
k3=9.043e9 ;
E1=9758.3  ;
E2=9758.3  ;
E3=8560    ;
dH1=4200   ;
dH2=-11000 ;
dH3=-41850 ;
ro=1000    ;
cp=2.8121  ;
caf=5.5    ;
cbf=0      ;
ccf=0      ;
cdf=0      ;
tf=378     ;

y(1)=(V/u(1)                                );
y(2)=(U*A*( x(5) - u(2) )                   );
y(3)=(k1*exp( -E1/x(5) )                    );
y(4)=(k2*exp( -E2/x(5) )                    );
y(5)=(k3*exp( -E3/x(5) )                    );
y(6)=(-( dH1*y(3) + dH2*y(4) + dH3*y(5) )*V );

dx(1)=(( caf - x(1) / y(1) ) - y(3) * x(1) - y(5) * x(1)^2  )*tal;
dx(2)=(( cbf - x(2) / y(1) ) + y(3) * x(1) - y(4) * x(2)    )*tal;
dx(3)=(( ccf - x(3) / y(1) ) +  y(4) * x(2)                 )*tal;
dx(4)=(( cdf - x(4) / y(1) ) +  1/2 * x(3)                  )*tal;
dx(5)=(( ( tf - x(5) )/ y(1)) + ( ( y(6) - y(2) )/ro*V*cp ) )*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
